import math

def tau(n):
    """Calculates the total number of divisors of n, tau(n)."""
    if n == 1:
        return 1
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def d(n):
    """Calculates the number of positive divisors of n other than 1 and n."""
    if n <= 0:
        return -1 # Should not happen based on problem constraints (positive integers)

    if n == 1:
        # Divisors: {1}. Excluding 1 and itself leaves 0.
        return 0

    # For n > 1, the total number of divisors is tau(n).
    # We exclude 1 and n, so we subtract 2.
    return tau(n) - 2

# Search parameters
N_MAX = 1000
min_a = float('inf')
best_n = -1
found = False

print(f"Starting search for n from 1 to {N_MAX}...")

for n in range(1, N_MAX + 1):
    n_plus_735 = n + 735

    a_n = d(n)
    a_n_plus_735 = d(n_plus_735)

    if a_n == a_n_plus_735:
        a = a_n

        # We are looking for the LEAST nonnegative integer a
        if a < min_a:
            min_a = a
            best_n = n
            found = True
            # Optimization: If we found a=0, it is the absolute minimum possible, so we can stop immediately.
            if a == 0:
                break

# Output results
if found:
    print(f"\n--- Search Results (n <= {N_MAX}) ---")
    print(f"Minimum non-negative a found: {min_a}")
    print(f"Corresponding n: {best_n}")
else:
    print("\nNo match found for n <= 1000.")

# Check the minimum possible value (a=0) explicitly
if min_a > 0:
    print("\nConfirmation Check: The least possible value for a is 0. If no match was found yet, we must determine if a=0 is achievable outside this range.")
else:
    print("\nSince min_a <= 0, the minimum has been found.")

# Define d(n) = tau(n) - 2 for n > 1. d(1) = 0.
def tau(n):
    if n == 1:
        return 1
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def d(n):
    if n == 1:
        return 0
    return tau(n) - 2

# Test Candidate B: a=2. Check if there exists n such that d(n) = 2 and d(n+735) = 2.
n = 10
d_n = d(n)
d_n_plus_735 = d(n + 735)

print(f"For n={n}: d(n) = {d_n}")
print(f"For n+735={n+735}: d(n+735) = {d_n_plus_735}")

if d_n == 2 and d_n_plus_735 == 2:
    print("Candidate B satisfied.")
